    from functools import lru_cache

    @lru_cache(None)
    def dp(rolls_left, current_max):
        if rolls_left == 0:
            return current_max

        stop_here = current_max
        roll_again = sum(dp(rolls_left - 1, max(current_max, i)) for i in range(1, n + 1)) / n

        return max(stop_here, roll_again)

    return dp(k, 0)

